inline void enc_value(std::string& out, const Value& v, int depth) {
    CompactEncodedCounter encoded_counter(out.size());
    if (const auto n = static_cast<std::uint64_t>(v.text.size()); n > 4096ULL) throw Refusal("bad_value",0);
    for (std::size_t i = 0; i < v.text.size(); ++i) { const auto c = static_cast<unsigned char>(v.text[i]); if (c < 0x20 || c == 0x7f || (c == 0xc2 && i + 1 < v.text.size() && static_cast<unsigned char>(v.text[i + 1]) <= 0x9f)) throw Refusal("bad_value",0); }
    if (const auto n = static_cast<std::uint64_t>(v.choice.size()); n != 0 && (n < 1ULL || n > 64ULL)) throw Refusal("bad_value",0);
    for (const char ch : v.choice) { const auto c = static_cast<unsigned char>(ch); if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '.' || c == '-')) throw Refusal("bad_value",0); }
    if (const auto n = static_cast<std::uint64_t>(v.text_list.size()); n > 128ULL) throw Refusal("bad_value",0);
    for (const auto& oaElement : v.text_list) {
    if (const auto n = static_cast<std::uint64_t>(oaElement.size()); n < 1ULL || n > 128ULL) throw Refusal("bad_value",0);
    }
    for (const auto& oaElement : v.text_list) {
    for (std::size_t i = 0; i < oaElement.size(); ++i) { const auto c = static_cast<unsigned char>(oaElement[i]); if (c < 0x20 || c == 0x7f || (c == 0xc2 && i + 1 < oaElement.size() && static_cast<unsigned char>(oaElement[i + 1]) <= 0x9f)) throw Refusal("bad_value",0); }
    }
    if (const auto n = static_cast<std::uint64_t>(v.text_map.size()); n > 8ULL) throw Refusal("bad_value",0);
    for (const auto& oaEntry : v.text_map) { const auto& oaElement = oaEntry.first;
    if (const auto n = static_cast<std::uint64_t>(oaElement.size()); n < 1ULL || n > 64ULL) throw Refusal("bad_value",0);
    }
    for (const auto& oaEntry : v.text_map) { const auto& oaElement = oaEntry.first;
    for (const char ch : oaElement) { const auto c = static_cast<unsigned char>(ch); if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '.' || c == '-')) throw Refusal("bad_value",0); }
    }
    for (const auto& oaEntry : v.text_map) { const auto& oaElement = oaEntry.second;
    if (const auto n = static_cast<std::uint64_t>(oaElement.size()); n > 512ULL) throw Refusal("bad_value",0);
    }
    for (const auto& oaEntry : v.text_map) { const auto& oaElement = oaEntry.second;
    for (std::size_t i = 0; i < oaElement.size(); ++i) { const auto c = static_cast<unsigned char>(oaElement[i]); if (c < 0x20 || c == 0x7f || (c == 0xc2 && i + 1 < oaElement.size() && static_cast<unsigned char>(oaElement[i + 1]) <= 0x9f)) throw Refusal("bad_value",0); }
    }
    if (wire_name(v.kind).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "kind");
    out += ": ";
    esc(out, std::string(wire_name(v.kind)));
    encoded_counter.check(out, 262144);
    if (v.boolean) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "boolean");
        out += ": ";
        out += v.boolean ? "true" : "false";
    }
    encoded_counter.check(out, 262144);
    if (v.integer != 0) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "integer");
        out += ": ";
        num(out, v.integer);
    }
    encoded_counter.check(out, 262144);
    if (v.bytes != 0) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "bytes");
        out += ": ";
        num(out, v.bytes);
    }
    encoded_counter.check(out, 262144);
    if (v.duration_ms != 0) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "duration_ms");
        out += ": ";
        num(out, v.duration_ms);
    }
    encoded_counter.check(out, 262144);
    if (!v.text.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "text");
        out += ": ";
        esc(out, v.text);
    }
    encoded_counter.check(out, 262144);
    if (!v.choice.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "choice");
        out += ": ";
        esc(out, v.choice);
    }
    encoded_counter.check(out, 262144);
    if (!v.text_list.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "text_list");
        out += ": ";
        strs(out, v.text_list, depth + 1);
    }
    encoded_counter.check(out, 262144);
    if (!v.text_map.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "text_map");
        out += ": ";
        strmap(out, v.text_map, depth + 1);
    }
    encoded_counter.check(out, 262144);
    out += '\n';
    pad(out, depth);
    out += '}';
    encoded_counter.check(out, 262144);
}

