inline void enc_key_origin(std::string& out, const KeyOrigin& v, int depth) {
    if (const auto n = static_cast<std::uint64_t>(v.path.size()); n > 4096ULL) throw Refusal("bad_value",0);
    for (std::size_t i = 0; i < v.path.size(); ++i) { const auto c = static_cast<unsigned char>(v.path[i]); if (c < 0x20 || c == 0x7f || (c == 0xc2 && i + 1 < v.path.size() && static_cast<unsigned char>(v.path[i + 1]) <= 0x9f)) throw Refusal("bad_value",0); }
    if (const auto n = static_cast<std::uint64_t>(v.reason.size()); n > 512ULL) throw Refusal("bad_value",0);
    for (std::size_t i = 0; i < v.reason.size(); ++i) { const auto c = static_cast<unsigned char>(v.reason[i]); if (c < 0x20 || c == 0x7f || (c == 0xc2 && i + 1 < v.reason.size() && static_cast<unsigned char>(v.reason[i + 1]) <= 0x9f)) throw Refusal("bad_value",0); }
    if (const auto n = static_cast<std::uint64_t>(v.shadowed.size()); n > 3ULL) throw Refusal("bad_value",0);
    if (v.location != Location{} && wire_name(v.location).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    bool first = true;
    if (v.location != Location{}) {
        first = false;
        out += '\n';
        pad(out, depth + 1);
        esc(out, "location");
        out += ": ";
        esc(out, std::string(wire_name(v.location)));
    }
    if (!first) out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "path");
    out += ": ";
    esc(out, v.path);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "state");
    out += ": ";
    esc(out, v.state);
    if (!v.reason.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "reason");
        out += ": ";
        esc(out, v.reason);
    }
    if (!v.shadowed.empty()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "shadowed");
        out += ": ";
        enc_list<ConfigSource>(out, v.shadowed, depth + 1, enc_config_source);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

