inline void enc_key_refusal(std::string& out, const KeyRefusal& v, int depth) {
    if (const auto n = static_cast<std::uint64_t>(v.key.size()); n < 1ULL || n > 64ULL) throw Refusal("bad_value",0);
    for (const char ch : v.key) { const auto c = static_cast<unsigned char>(ch); if (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '.' || c == '-')) throw Refusal("bad_value",0); }
    if (wire_name(v.reason).empty()) throw Refusal("bad_enum", 0);
    out += '{';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "key");
    out += ": ";
    esc(out, v.key);
    out += ',';
    out += '\n';
    pad(out, depth + 1);
    esc(out, "reason");
    out += ": ";
    esc(out, std::string(wire_name(v.reason)));
    if (v.refusal.has_value()) {
        out += ',';
        out += '\n';
        pad(out, depth + 1);
        esc(out, "refusal");
        out += ": ";
        enc_oa_imported0(out, *v.refusal, depth + 1);
    }
    out += '\n';
    pad(out, depth);
    out += '}';
}

