inline Snapshot decode(std::string_view data) {
    detail::Reader r{data};
    r.skip_ws();
    Snapshot v = detail::decode_snapshot(r);
    r.skip_ws();
    if (r.pos < r.buf.size()) r.refuse("trailing_bytes");
    return v;
}

// to_json writes one record as JSON, laid out as this definition's documents
// are and without the document terminator; from_json<T> reads one and throws
// Refusal for what the record's reader refuses.
template <class T> T from_json(std::string_view data);

inline std::string to_json(const RunOverrides& v) {
    std::string out;
    detail::enc_run_overrides(out, v, 0);
    return out;
}

template <> inline RunOverrides from_json<RunOverrides>(std::string_view data) {
    detail::Reader r{data};
    r.skip_ws();
    RunOverrides v = detail::decode_run_overrides(r);
    r.skip_ws();
    if (r.pos < r.buf.size()) r.refuse("trailing_bytes");
    return v;
}

